// ListByServiceAll iterates every tasks across every page of ListByService.
// Follows nextCursor until the server reports no further page. Yields (item, nil) per item and,
// on a failure mid-iteration, one final (zero, err) — so a partial walk is never mistaken for a
// complete one.
func (s *TasksService) ListByServiceAll(ctx context.Context, serviceID string, query *TasksListByServiceQuery) iter.Seq2[PublicTaskListItem, error] {
	return func(yield func(PublicTaskListItem, error) bool) {
		var page TasksListByServiceQuery
		if query != nil {
			page = *query
		}
		for {
			result, err := s.ListByService(ctx, serviceID, &page)
			if err != nil {
				var zero PublicTaskListItem
				yield(zero, err)
				return
			}
			for _, item := range result.Tasks {
				if !yield(item, nil) {
					return
				}
			}
			if result.NextCursor == nil || *result.NextCursor == "" {
				return
			}
			if page.Cursor != nil && *page.Cursor == *result.NextCursor {
				var zero PublicTaskListItem
				yield(zero, ErrRepeatedCursor)
				return
			}
			page.Cursor = result.NextCursor
		}
	}
}

